const menuToggle=document.querySelector(".menu-toggle"),navLinks=document.querySelector(".nav-links");menuToggle.addEventListener("click",()=>{navLinks.classList.toggle("active")});const startYear=2026,currentYear=(new Date).getFullYear(),yearText=currentYear>2026?`2026-${currentYear}`:"2026";document.getElementById("copyright-year").textContent=yearText;const targetDate=new Date(2027,6,24,13,0,0),daysEl=document.getElementById("days"),hoursEl=document.getElementById("hours"),minutesEl=document.getElementById("minutes"),secondsEl=document.getElementById("seconds"),debugEl=document.getElementById("debug"),countdownEl=document.getElementById("countdown");function pad(n){return String(n).padStart(2,"0")}function updateCountdown(){const now=new Date,diffMs=targetDate-now;if(diffMs<=0)return countdownEl.innerHTML='<div class="finished">🎉 Time reached!</div>',debugEl.textContent="Target was: "+targetDate.toString(),void clearInterval(timer);const totalSeconds=Math.floor(diffMs/1e3),days=Math.floor(totalSeconds/86400),hours=Math.floor(totalSeconds%86400/3600),minutes=Math.floor(totalSeconds%3600/60),seconds=totalSeconds%60;daysEl.textContent=days,hoursEl.textContent=pad(hours),minutesEl.textContent=pad(minutes),secondsEl.textContent=pad(seconds),debugEl.textContent="now: "+now.toString()+" | target: "+targetDate.toString()+" | diffMs: "+diffMs}updateCountdown();const timer=setInterval(updateCountdown,1e3);